changeSet.sql:
INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.form058-received.enabled', 'true', 'BOOLEAN', 'Notify the receiver organization when a new Form058 arrives.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.form058-received.enabled');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.form058-acknowledged.enabled', 'true', 'BOOLEAN', 'Notify the sender organization when a Form058 is accepted by the receiver (SENT -> ACCEPTED).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.form058-acknowledged.enabled');

